package com.example.payment.integrationtest.paymentgateway;

import static com.github.tomakehurst.wiremock.client.WireMock.aResponse;
import static com.github.tomakehurst.wiremock.client.WireMock.equalToJson;
import static com.github.tomakehurst.wiremock.client.WireMock.post;
import static com.github.tomakehurst.wiremock.client.WireMock.postRequestedFor;
import static com.github.tomakehurst.wiremock.client.WireMock.urlEqualTo;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.github.tomakehurst.wiremock.WireMockServer;
import com.github.tomakehurst.wiremock.core.WireMockConfiguration;
import java.math.BigDecimal;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

class HttpPaymentGatewayTest {

    private static final String PATH = "/v1/authorizations";

    private WireMockServer provider;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void start() {
        provider = new WireMockServer(WireMockConfiguration.options().dynamicPort());
        provider.start();
        gateway = new HttpPaymentGateway(RestClient.builder().baseUrl(provider.baseUrl()).build());
    }

    @AfterEach
    void stop() {
        provider.stop();
    }

    private static Money twelveEuros() {
        return new Money(new BigDecimal("12.50"), "eur");
    }

    private void providerAnswers(int status, String body) {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(aResponse()
                .withStatus(status)
                .withHeader("Content-Type", "application/json")
                .withBody(body)));
    }

    @Test
    void it_posts_the_reference_amount_and_currency_as_json() {
        providerAnswers(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", twelveEuros());

        provider.verify(1, postRequestedFor(urlEqualTo(PATH))
                .withHeader("Content-Type", com.github.tomakehurst.wiremock.client.WireMock.containing("application/json"))
                .withRequestBody(equalToJson("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}", false, false)));
    }

    @Test
    void an_approved_answer_is_approved() {
        providerAnswers(200, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_declined() {
        providerAnswers(200, "{\"status\":\"declined\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void unknown_extra_fields_in_the_answer_are_ignored() {
        providerAnswers(200, "{\"status\":\"approved\",\"id\":\"auth_1\",\"risk\":{\"score\":3}}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_402_refusal_is_declined_whatever_its_body() {
        providerAnswers(402, "{\"error\":\"card_refused\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_without_a_body_is_declined() {
        provider.stubFor(post(urlEqualTo(PATH)).willReturn(aResponse().withStatus(402)));

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unrecognised_status_is_never_treated_as_approved() {
        providerAnswers(200, "{\"status\":\"pending\"}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_approved() {
        providerAnswers(200, "{}");

        assertThat(gateway.authorize("ORD-7", twelveEuros())).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_is_an_error_not_a_decline() {
        providerAnswers(400, "{\"error\":\"invalid_request\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-7", twelveEuros()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_failure_is_an_error_not_a_decline() {
        providerAnswers(500, "{\"error\":\"boom\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-7", twelveEuros()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }

    @Test
    void an_answer_that_is_not_json_is_an_error() {
        providerAnswers(200, "<html>oops</html>");

        assertThatThrownBy(() -> gateway.authorize("ORD-7", twelveEuros())).isInstanceOf(RuntimeException.class);
    }
}
